    state.tasks=(payload.tasks||[]).map(function(t){return {id:t.id,userId:t.user_id,title:t.title,level:t.task_level||'—',description:t.description||'',status:t.status,progress:Number(t.progress)||0,reward:Number(t.reward)||0,start:isoDate(t.start_date),due:isoDate(t.due_date),nodeId:t.related_node_id}});
    state.referrals=(payload.referrals||[]).map(function(r){return {id:r.id,userId:r.user_id,referredUserId:r.referred_user_id,level:Number(r.referral_level)||1,reward:Number(r.platform_reward)||0,created:isoDate(r.created_at)}});
