  async function hydrateRemote(){
    if(!supa)return;
    var results=await Promise.all([
      supa.from('users').select('*'),
      supa.from('active_nodes').select('*'),
      supa.from('tasks').select('*'),
      supa.from('referrals').select('*'),
      supa.from('withdrawal_requests').select('*'),
      supa.from('activity_logs').select('*').order('created_at',{ascending:false}).limit(100),
      supa.from('notifications').select('*').order('created_at',{ascending:false}).limit(100)
    ]);
    for(var i=0;i<results.length;i++){if(remoteError(results[i]))throw remoteError(results[i]);}
    mapRemoteState({users:results[0].data,nodes:results[1].data,tasks:results[2].data,referrals:results[3].data,withdrawals:results[4].data,activity:results[5].data,notifications:results[6].data});
    var p=me();if(p)p.nodeCount=state.nodes.filter(function(n){return n.userId===p.id}).length;
  }
  async function bootRemote(){
    try{
      var s=await supa.auth.getSession();
      if(s&&s.data&&s.data.session&&s.data.session.user){
        var claimed=await supa.rpc('claim_aegispay_profile');
        if(claimed.error)throw claimed.error;
        session={id:claimed.data.id,authId:s.data.session.user.id,email:s.data.session.user.email};
        saveSession();
        await hydrateRemote();
      }else{
        session=null;
        saveSession();
      }
    }catch(e){
      session=null;
      saveSession();
    }
    render();
  }
  function loadState(){try{return JSON.parse(localStorage.getItem('aegispay_demo_state'))||clone(SEED)}catch(e){return clone(SEED)}}
  function loadSession(){try{return JSON.parse(localStorage.getItem('aegispay_demo_session')||'null')}catch(e){return null}}
  function saveState(){localStorage.setItem('aegispay_demo_state',JSON.stringify(state));}
  function saveSession(){if(session)localStorage.setItem('aegispay_demo_session',JSON.stringify(session));else localStorage.removeItem('aegispay_demo_session')}
  function me(){return session&&state.users.find(function(u){return u.id===session.id})||session}
  function isAdmin(){return ['ADMIN','MASTER ADMIN'].indexOf(me()&&me().role)>=0}
  function isMaster(){return me()&&me().role==='MASTER ADMIN'}
  function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n)||0)}
  function esc(v){return String(v==null?'':v).replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})}
  function badge(s){var cls={'ACTIVE':'good','APPROVED':'good','Completed':'good','COMPLETE':'good','OK':'good','SYNCED':'info','RECORDED':'info','In Progress':'info','PENDING_APPROVAL':'warn','Pending':'warn','PENDING':'warn','REJECTED':'bad','Expired':'bad'}[s]||'';return '<span class="badge '+cls+'">'+esc(String(s).replace(/_/g,' '))+'</span>'}
  function toast(msg,type){var wrap=document.querySelector('.toast-wrap');if(!wrap){wrap=document.createElement('div');wrap.className='toast-wrap';document.body.appendChild(wrap)}var el=document.createElement('div');el.className='card';el.style='padding:11px 13px;font-size:11px;max-width:360px;border-color:'+(type==='bad'?'rgba(255,107,129,.3)':type==='good'?'rgba(66,230,164,.3)':'var(--line)');el.textContent=msg;wrap.appendChild(el);setTimeout(function(){el.remove()},3200)}
  function nav(id,label,icon,roles){if(roles&&roles.indexOf(me().role)<0)return'';return '<button class="nav-btn '+(page===id?'active':'')+'" onclick="Aegis.go(\''+id+'\')"><span class="nav-ico">'+icon+'</span><span>'+label+'</span></button>'}
