  function shell(body){var unread=state.notifications.filter(function(n){return !n.read}).length;return '<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">A</div><div class="brand-copy"><b>AegisPay</b><small>Operations Platform</small></div></div><div class="nav-group"><div class="nav-label">Platform</div>'+nav('dashboard','Dashboard','⌂')+nav('nodes','My Nodes','◈')+nav('tasks','Tasks','✓')+nav('referrals','Referrals','◎')+nav('activity','Activity','◌')+nav('withdrawals','Withdrawals','↗')+nav('ai','AI Assistant','✦')+nav('profile','Profile','◉')+(isAdmin()?'<div class="nav-label">Administration</div>':'')+nav('admin','Admin Dashboard','▦',['ADMIN','MASTER ADMIN'])+nav('users','Users','♙',['ADMIN','MASTER ADMIN'])+nav('manage-nodes','Node Management','◇',['ADMIN','MASTER ADMIN'])+nav('manage-tasks','Task Management','✓',['ADMIN','MASTER ADMIN'])+nav('manage-referrals','Referral Management','◎',['ADMIN','MASTER ADMIN'])+nav('approvals','Approval Center','✓',['MASTER ADMIN'])+nav('logs','Audit Logs','≡',['ADMIN','MASTER ADMIN'])+nav('settings','Settings','⚙',['ADMIN','MASTER ADMIN'])+nav('ops','System Operations','◫',['MASTER ADMIN'])+'</div><div class="sidebar-foot">AegisPay Platform · Data only<br>Secure platform operations · Demo mode<br>No real payments are executed.</div></aside><main><header class="topbar"><div class="topbar-left"><button class="btn mobile-menu" onclick="Aegis.toggleMenu()">☰</button><div><b>'+esc(label(page))+'</b><small>AegisPay control-center workspace</small></div></div><div class="topbar-actions"><button class="btn desktop-only" onclick="Aegis.go(\'notifications\')">Notifications'+(unread?' · '+unread:'')+'</button>'+badge(me().role)+'<button class="btn" onclick="Aegis.logout()">Logout</button></div></header>'+body+footer()+'<div class="mobile-nav">'+navMobile('dashboard','Home')+navMobile('nodes','Nodes')+navMobile('tasks','Tasks')+navMobile('profile','Profile')+'</div></main></div>'}
  function navMobile(id,t){return '<button class="'+(page===id?'active':'')+'" onclick="Aegis.go(\''+id+'\')">'+t+'</button>'}
