  function label(id){var m={dashboard:'Operations Dashboard',nodes:'My Nodes',tasks:'Tasks',referrals:'Referrals',activity:'Activity Stream',withdrawals:'Withdrawals',ai:'AI Strategy Assistant',profile:'Profile',notifications:'Notifications',admin:'Admin Dashboard',users:'User Management','manage-nodes':'Node Management','manage-tasks':'Task Management','manage-referrals':'Referral Management',approvals:'Approval Center',logs:'Audit Logs',settings:'Platform Settings',ops:'System Operations'};return m[id]||'AegisPay'}
  function map(){var pts=[['New York',19,38],['London',37,31],['Dubai',56,44],['Singapore',74,58],['Tokyo',84,35],['Sydney',88,73],['Mexico City',24,66]];return '<div class="map"><div class="world-line"></div>'+pts.map(function(p){return '<div class="map-node" style="left:'+p[1]+'%;top:'+p[2]+'%"><span>'+esc(p[0])+'</span></div>'}).join('')+'</div>'}
  function heatmap(){var cells=[['NY',.8],['LDN',.62],['DXB',.71],['SG',.93],['TKY',.78],['SYD',.52],['MEX',.38],['PAR',.26],['TOR',.34],['IST',.48],['HKG',.81],['SIN',.88]];return '<div class="heatmap">'+cells.map(function(c){var cls=c[1]>.84?'vhot':c[1]>.55?'hot':'';return '<div class="heat-cell '+cls+'">'+c[0]+'<br>'+Math.round(c[1]*100)+'%</div>'}).join('')+'</div>'}
