  function tasks(){var list=state.tasks.filter(function(t){return t.userId===me().id});return shell('<section class="page">'+hero('Tasks','Task-based activity, completion history and platform rewards.')+'<div class="grid cards">'+(list.length?list.map(taskCard).join(''):'<div class="empty"><strong>No tasks available.</strong>Your current task queue is empty.</div>')+'</div></section>')}
  function taskCard(t){return '<div class="card"><div class="card-title"><h3>'+esc(t.title)+'</h3>'+badge(t.status)+'</div><div class="kpi"><span>Level</span><b>'+esc(t.level)+'</b></div><div class="kpi"><span>Progress</span><b>'+t.progress+'%</b></div><div class="progress"><span style="width:'+t.progress+'%"></span></div><p class="muted" style="font-size:11px;line-height:1.5">'+esc(t.description)+'</p><div class="kpi"><span>Platform reward</span><b>'+money(t.reward)+'</b></div><div class="kpi"><span>Due</span><b>'+esc(t.due)+'</b></div><button class="btn '+(t.status==='Completed'?'':'primary')+'" style="margin-top:10px;width:100%" '+(t.status==='Completed'?'disabled':'')+' onclick="Aegis.completeTask(\''+t.id+'\')">'+(t.status==='Completed'?'Completed':'Mark Complete')+'</button></div>'}
  function referrals(){var u=me(),rs=state.referrals.filter(function(r){return r.userId===u.id}),direct=state.users.filter(function(x){return x.referrer===u.referralCode}),second=state.users.filter(function(x){return x.referrer&&direct.some(function(d){return d.referralCode===x.referrer})});return shell('<section class="page">'+hero('Referral Network','Multi-tier referral structure with levels 1–3 and platform reward records.')+'<div class="grid four"><div class="card metric"><span>Referral Code</span><strong style="font-size:22px">'+esc(u.referralCode)+'</strong></div><div class="card metric"><span>Direct Referrals</span><strong>'+direct.length+'</strong></div><div class="card metric"><span>Network Size</span><strong>'+(direct.length+second.length)+'</strong></div><div class="card metric"><span>Platform Rewards</span><strong>'+money(rs.reduce(function(a,r){return a+r.reward},0))+'</strong></div></div><div style="height:16px"></div><div class="grid two"><div class="card"><div class="card-title"><h3>Referral Tree</h3><span>Levels 1–3</span></div><div class="ref-tree"><div class="ref-node me">'+esc(u.name)+'<br><small style="color:var(--muted)">'+esc(u.referralCode)+'</small></div><div class="muted">↓</div><div class="ref-level">'+(direct.length?direct.map(function(x){return '<div class="ref-node">'+esc(x.name)+'<br><small style="color:var(--muted)">Level 1</small></div>'}).join(''):'<div class="muted">No level 1 activity yet.</div>')+'</div><div class="muted">↓</div><div class="ref-level">'+(second.length?second.map(function(x){return '<div class="ref-node">'+esc(x.name)+'<br><small style="color:var(--muted)">Level 2</small></div>'}).join(''):'<div class="muted">No level 2 activity yet.</div>')+'</div></div></div><div class="card"><div class="card-title"><h3>Referral Link</h3><span>System generated</span></div><input class="input" readonly value="https://aegispay.demo/ref/'+esc(u.referralCode)+'"><button class="btn primary" style="margin-top:9px;width:100%" onclick="Aegis.copyReferral()">Copy Referral Link</button><div style="height:12px"></div>'+rs.map(function(r){return '<div class="kpi"><span>Level '+r.level+' · '+esc(r.referredUserId)+'</span><b>'+money(r.reward)+'</b></div>'}).join('')+'</div></div></section>')}
