  function withdrawals(){var ws=state.withdrawals.filter(function(w){return w.userId===me().id});return shell('<section class="page">'+hero('Withdrawals','Request tracking, risk scoring and administrator approval status.')+'<div class="grid two"><div class="card"><div class="card-title"><h3>New Withdrawal Request</h3><span>No real payment processing</span></div><div class="form-grid"><div class="field"><label>Amount</label><input id="wdAmount" class="input" type="number" min="1" placeholder="100"></div><div class="field"><label>Destination Address</label><input id="wdDest" class="input" placeholder="Destination"></div><div class="full"><button class="btn primary" onclick="Aegis.requestWithdrawal()">Submit Request</button></div></div></div><div class="card"><div class="card-title"><h3>Request Guidelines</h3><span>Platform workflow</span></div><div class="kpi"><span>Validation</span><b>Amount &gt; 0</b></div><div class="kpi"><span>Destination</span><b>Required</b></div><div class="kpi"><span>Risk score</span><b>0.00–1.00 demo</b></div><div class="kpi"><span>Initial status</span><b>PENDING_APPROVAL</b></div><div class="info-box" style="margin-top:10px">After submission, the platform creates a request, assigns a system risk score, records it in the queue and performs no real payment.</div></div></div><div style="height:16px"></div><div class="card"><div class="card-title"><h3>Withdrawal History</h3><span>'+ws.length+' records</span></div>'+tableWithdrawal(ws)+'</div></section>')}
