  function ai(){return shell('<section class="page">'+hero('AI Strategy Assistant','Context-aware informational assistance using current platform data.')+'<div class="grid two"><div class="card"><div id="chat" class="chat"><div class="info-box">Informational platform only; not individualized financial advice.</div></div><div class="form-grid"><input id="aiInput" class="input" placeholder="Ask about nodes, tasks, referrals, liquidity or withdrawals" onkeydown="if(event.key===\'Enter\')Aegis.askAI()"><button class="btn primary" onclick="Aegis.askAI()">Send</button></div></div><div class="card"><div class="card-title"><h3>Suggested Questions</h3><span>Current data</span></div>'+['What is my current node status?','What tasks are pending?','Explain my referral network.','Explain the current platform liquidity metrics.','What is the status of my withdrawal request?'].map(function(q){return '<button class="btn" style="display:block;width:100%;margin-bottom:7px;text-align:left" onclick="Aegis.askAI('+JSON.stringify(q)+')">'+esc(q)+'</button>'}).join('')+'</div></div></section>')}
  function answerAI(q){var l=q.toLowerCase(),u=me();if(l.indexOf('node')>=0){var ns=state.nodes.filter(function(n){return n.userId===u.id});return 'You currently have '+ns.length+' active node record(s): '+ns.map(function(n){return n.tier+' in '+n.region}).join(', ')+'.'}if(l.indexOf('task')>=0){var ts=state.tasks.filter(function(t){return t.userId===u.id}),o=ts.filter(function(t){return t.status!=='Completed'});return 'You have '+o.length+' open task(s). '+o.map(function(t){return t.title+' ('+t.progress+'%)'}).join(', ')+'.'}if(l.indexOf('referral')>=0){var rs=state.referrals.filter(function(r){return r.userId===u.id});return 'Your current referral records are '+rs.length+' with '+money(rs.reduce(function(a,r){return a+r.reward},0))+' in platform reward data.'}if(l.indexOf('liquidity')>=0)return 'System liquidity is 98.4%, reserves are '+money(98400)+' and liabilities are '+money(100000)+'. This is system data, not an independent financial audit.';if(l.indexOf('withdraw')>=0){var ws=state.withdrawals.filter(function(w){return w.userId===u.id});return 'You have '+ws.length+' withdrawal record(s); '+ws.filter(function(w){return w.status==='PENDING_APPROVAL'}).length+' are pending approval. Status changes are workflow records only.'}return 'I can explain current nodes, tasks, referrals, liquidity metrics or withdrawal status from the demonstration dataset.'}
  function profile(){var u=me(),ns=state.nodes.filter(function(n){return n.userId===u.id}),rs=state.referrals.filter(function(r){return r.userId===u.id}),ts=state.tasks.filter(function(t){return t.userId===u.id});return shell('<section class="page">'+hero('Profile','Account identity and current platform statistics.')+'<div class="grid two"><div class="card"><div class="card-title"><h3>Account</h3>'+badge(u.role)+'</div>'+[['Name',u.name],['Email',u.email],['User ID',u.id],['Role',u.role],['Referral Code',u.referralCode],['Created',u.created]].map(function(x){return '<div class="kpi"><span>'+esc(x[0])+'</span><b>'+esc(x[1])+'</b></div>'}).join('')+'</div><div class="card"><div class="card-title"><h3>Current Statistics</h3><span>System data</span></div>'+[['Platform balance',money(u.balance)],['Active nodes',ns.length],['Referral records',rs.length],['Task records',ts.length],['Completed tasks',ts.filter(function(t){return t.status==='Completed'}).length]].map(function(x){return '<div class="kpi"><span>'+esc(x[0])+'</span><b>'+esc(x[1])+'</b></div>'}).join('')+'</div></div></section>')}
  function notifications(){return shell('<section class="page">'+hero('Notifications','Application notifications for tasks, nodes, referrals and withdrawals.','<button class="btn" onclick="Aegis.markAllRead()">Mark all read</button>')+'<div class="card">'+state.notifications.map(function(n){return '<div class="activity-row"><div class="dot" style="background:'+(n.read?'#4f627f':'var(--accent)')+'"></div><div><b>'+esc(n.title)+'</b><small>'+esc(n.text)+'</small></div><div class="activity-time">'+esc(n.time)+' · '+(n.read?'Read':'Unread')+'</div></div>'}).join('')+'</div></section>')}
