  function adminTable(title,heads,data,key){if(!isAdmin())return forbidden();var f=filters[key]||{},q=(f.q||'').toLowerCase(),rows=data.filter(function(row){return !q||row.join(' ').toLowerCase().indexOf(q)>=0}),pg=pageNums[key]||1,size=6,start=(pg-1)*size,show=rows.slice(start,start+size),total=Math.max(1,Math.ceil(rows.length/size));if(pg>total){pg=1;pageNums[key]=1;start=0;show=rows.slice(0,size)}return shell('<section class="page">'+hero(title,'Authorized administrative records with search and pagination.')+'<div class="card"><div class="toolbar"><input class="input grow" placeholder="Search '+key+'" value="'+esc(f.q||'')+'" oninput="Aegis.tableSearch(\''+key+'\',this.value)"><span class="badge info">'+rows.length+' matches</span></div><div class="table-wrap"><table class="table"><tr>'+heads.map(function(h){return '<th>'+esc(h)+'</th>'}).join('')+'</tr>'+show.map(function(row){return '<tr>'+row.map(function(v){return '<td>'+esc(v)+'</td>'}).join('')+'</tr>'}).join('')+'</table></div><div class="pager"><small>Showing '+(rows.length?start+1:0)+'–'+Math.min(start+size,rows.length)+' of '+rows.length+'</small><div><button class="btn" onclick="Aegis.tablePage(\''+key+'\','+Math.max(1,pg-1)+')">Prev</button> <button class="btn" onclick="Aegis.tablePage(\''+key+'\','+Math.min(total,pg+1)+')">Next</button></div></div></div></section>')}
  function approvals(){if(!isMaster())return forbidden();var list=state.withdrawals;return shell('<section class="page">'+hero('Approval Center','Master Admin final platform approval workflow.','<button class="btn" onclick="Aegis.go(\'notifications\')">Notification Queue</button>')+'<div class="card"><div class="alert">Telegram approval workflow is represented conceptually: request → risk score → notification payload → admin decision → status/audit record. No real payment is executed.</div><div style="height:12px"></div><div class="table-wrap"><table class="table"><tr><th>Request</th><th>User</th><th>Amount</th><th>Destination</th><th>Risk</th><th>Created</th><th>Status</th><th>Action</th></tr>'+list.map(function(w){return '<tr><td>'+esc(w.id)+'</td><td>'+esc(w.userId)+'</td><td>'+money(w.amount)+'</td><td>'+esc(w.destination)+'</td><td>'+w.risk.toFixed(2)+'</td><td>'+esc(w.created)+'</td><td>'+badge(w.status)+'</td><td>'+(w.status==='PENDING_APPROVAL'?'<button class="btn good" onclick="Aegis.approve(\''+w.id+'\',true)">Approve</button> <button class="btn bad" onclick="Aegis.approve(\''+w.id+'\',false)">Reject</button> <button class="btn" onclick="Aegis.withdrawDetail(\''+w.id+'\')">Details</button>':'<button class="btn" onclick="Aegis.withdrawDetail(\''+w.id+'\')">Details</button>')+'</td></tr>'}).join('')+'</table></div></div><div style="height:16px"></div><div class="grid two"><div class="card"><div class="card-title"><h3>Approval History</h3><span>Recorded decisions</span></div>'+list.filter(function(w){return w.status!=='PENDING_APPROVAL'}).map(function(w){return '<div class="kpi"><span>'+esc(w.id)+'</span><b>'+esc(w.status)+'</b></div>'}).join('')+'</div><div class="card"><div class="card-title"><h3>Telegram Payload Concept</h3><span>Preview only</span></div><textarea id="telegramPayload" class="textarea" rows="7" readonly>'+esc(JSON.stringify({event:'withdrawal_approval_request',requestId:list[0]&&list[0].id,mode:'DEMO',action:'APPROVE_OR_REJECT'},null,2))+'</textarea><button class="btn primary" style="margin-top:9px" onclick="Aegis.copyTelegramPayload()">Copy Payload</button></div></div></section>')}
  function logs(){return adminTable('Audit Logs',['Event ID','Event Type','Location','Description','Time','Status'],state.activity.map(function(a,i){return ['EVT-'+String(i+1).padStart(4,'0'),a.type,a.location,a.text,a.time,a.status]}),'logs')}
  function settings(){if(!isAdmin())return forbidden();return shell('<section class="page">'+hero('Platform Settings','Configuration, environment and notification preferences.')+'<div class="grid two"><div class="card"><div class="card-title"><h3>Configuration</h3><span>Safe demo controls</span></div><div class="kpi"><span>Platform mode</span><b>'+state.settings.systemMode+'</b></div><div class="kpi"><span>Refresh interval</span><b>'+state.settings.refreshInterval+' sec</b></div><div class="kpi"><span>Notifications</span><b>'+state.settings.notifications+'</b></div><div class="kpi"><span>Security alerts</span><b>'+state.settings.securityAlerts+'</b></div></div><div class="card"><div class="card-title"><h3>Data Controls</h3><span>Local demonstration</span></div><button class="btn bad" onclick="Aegis.resetData()">Reset Demonstration Data</button><div style="height:9px"></div><button class="btn" onclick="Aegis.exportData()">Export Demo JSON</button></div></div></section>')}
  function ops(){if(!isMaster())return forbidden();var services=[['Web Application','Operational','Static UI / role navigation'],['API Layer','Operational','Demo REST interface'],['Database Model','Prepared','PostgreSQL schema present'],['Notifications','Operational','Local system notification queue'],['Telegram Approval','Prepared','Conceptual payload only'],['Payment Execution','Disabled','No live payment integration']];return shell('<section class="page">'+hero('System Operations','Central operational status, service health and configuration visibility.')+'<div class="grid three">'+services.map(function(s){return '<div class="card"><div class="card-title"><h3>'+esc(s[0])+'</h3>'+badge(s[1].toUpperCase())+'</div><p class="muted" style="font-size:11px">'+esc(s[2])+'</p></div>'}).join('')+'</div><div style="height:16px"></div><div class="card"><div class="card-title"><h3>Operational Controls</h3><span>Demo-safe</span></div><button class="btn" onclick="Aegis.refreshData()">Refresh Data</button> <button class="btn" onclick="Aegis.go(\'logs\')">View Audit Logs</button> <button class="btn" onclick="Aegis.go(\'settings\')">Open Settings</button></div></section>')}
